// Package model holds hand-written model types that gqlgen binds against the
// schema's custom scalars and enums. Struct types for entities (Mesocycle,
// Week, Day, ...) are generated by gqlgen — do NOT re-declare them here.
package model

import (
	"encoding/json"
	"fmt"
	"io"

	"github.com/99designs/gqlgen/graphql"
)

// JSON is an arbitrary JSON value (object, array, scalar). Used as the
// "raw" passthrough on entity types, for user attributes, and as the input
// type for mutations that mirror RP's write payloads.
type JSON = json.RawMessage

// MarshalJSON implements graphql.Marshaler.
func MarshalJSON(b JSON) graphql.Marshaler {
	if len(b) == 0 {
		b = []byte("null")
	}
	return graphql.WriterFunc(func(w io.Writer) {
		_, _ = w.Write(b)
	})
}

// UnmarshalJSON implements graphql.Unmarshaler.
func UnmarshalJSON(v interface{}) (JSON, error) {
	switch t := v.(type) {
	case json.RawMessage:
		return t, nil
	case string:
		return JSON(t), nil
	default:
		data, err := json.Marshal(v)
		if err != nil {
			return nil, fmt.Errorf("marshal JSON: %w", err)
		}
		return JSON(data), nil
	}
}

// PriorityTier is the RP priority scale. Ordered low → high.
type PriorityTier string

const (
	PriorityTierMaintain  PriorityTier = "maintain"
	PriorityTierGrow      PriorityTier = "grow"
	PriorityTierEmphasize PriorityTier = "emphasize"
)

// IsValid reports whether the tier is one RP accepts.
func (p PriorityTier) IsValid() bool {
	switch p {
	case PriorityTierMaintain, PriorityTierGrow, PriorityTierEmphasize:
		return true
	}
	return false
}

// SetType is the RP set kind.
type SetType string

const (
	SetTypeRegular      SetType = "regular"
	SetTypeMyorep       SetType = "myorep"
	SetTypeMyorepMatch  SetType = "myorep-match" // API uses hyphen; schema used underscore
)

// GraphQL enum value → wire value. GraphQL enum names cannot contain hyphens.
func (s SetType) WireValue() string { return string(s) }
